// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class BindingSetAssignmentLiveRowsTest {

	@Test
	void readingRowsKeepsTheSuppliedIterableAndCallerMutation() {
		MapBindingSet row = new MapBindingSet();
		row.setBinding("x", SimpleValueFactory.getInstance().createLiteral("before"));
		List<BindingSet> rows = List.of(row);
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingSets(rows);
		assertSame(rows, assignment.getBindingSets());
		row.setBinding("x", SimpleValueFactory.getInstance().createLiteral("after"));
		assertEquals("after", assignment.getBindingSets().iterator().next().getValue("x").stringValue());
	}

	@Test
	void cloneAndHashDoNotTraverseOrFreezeRows() {
		AtomicInteger traversals = new AtomicInteger();
		Iterable<BindingSet> source = () -> {
			traversals.incrementAndGet();
			return List.<BindingSet>of(new MapBindingSet()).iterator();
		};
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingSets(source);
		BindingSetAssignment clone = assignment.clone();
		assertEquals(assignment, clone);
		assertEquals(assignment.hashCode(), clone.hashCode());
		assertSame(source, clone.getBindingSets());
		assertEquals(0, traversals.get(), "algebra access and cloning must not prepare or consume VALUES");
	}
}
